import Slider from "../components/Slider";
import Section from "../components/Section";
import PriceTable from "../components/PriceTable";

import copper from "../data/COPPER.json";
import brass from "../data/BRASS.json";
import aluminum from "../data/ALUMINUM.jsonjson";
import stainless from "../data/STAINLESS.json";
import circuitBoards from "../data/CIRCUITBOARD.json";
import cpus from "../data/CPU.json";
import ram from "../data/RAM.json";
import whole from "../data/WHOLE.json";

export default function Home() {
  return (
    <div>

      <Slider />

      <Section title="Copper">
        <PriceTable data={copper} />
      </Section>

      <Section title="Brass">
        <PriceTable data={brass} />
      </Section>

      <Section title="Aluminum">
        <PriceTable data={aluminum} />
      </Section>

      <Section title="Stainless Steel">
        <PriceTable data={stainless} />
      </Section>


      <Section title="Circuit Boards">
        <PriceTable data={circuitBoards} />
      </Section>

      <Section title="CPUs">
        <PriceTable data={cpus} />
      </Section>

      <Section title="Whole">
        <PriceTable data={whole} />
      </Section>

      <Section title="RAM">
        <PriceTable data={ram} />
      </Section>

    </div>
  );
}
